total_bytes = 0
for cid, obj in P.items():
    obj2 = {"case_id": cid, "prediction_text": obj["prediction_text"], "basis": obj["basis"],
            "confidence": obj["confidence"], "trigger": obj["trigger"]}
    s = json.dumps(obj2, ensure_ascii=False, indent=1)
    path = os.path.join(OUT, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        f.write(s + "\n")
    total_bytes += os.path.getsize(path)

# self-verify: re-read each file, parse, check keys & trigger shape
ok = 0
for cid in P:
    path = os.path.join(OUT, cid + ".json")
    d = json.load(open(path, encoding="utf-8"))
    assert set(d.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}, cid
    assert d["case_id"] == cid
    tr = d["trigger"]
    assert set(tr.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}, cid
    assert all(isinstance(tr[k], bool) for k in ("changed_main", "reserve_used", "disputed")), cid
    assert isinstance(tr["reason"], str) and isinstance(d["confidence"], (int, float)) and 0 <= d["confidence"] <= 1, cid
    assert "第八节" in d["basis"] and "功量核" in d["basis"] and "主线认定：" in d["basis"], cid
    assert "systems_used:" in d["basis"], cid
    ok += 1
cm = sum(1 for o in P.values() if o["trigger"]["changed_main"])
ru = sum(1 for o in P.values() if o["trigger"]["reserve_used"])
di = sum(1 for o in P.values() if o["trigger"]["disputed"])
print(f"cases={len(P)} written_ok={ok} total_bytes={total_bytes}")
print(f"trigger counts: changed_main={cm} reserve_used={ru} disputed={di}")
